def _classify_entity(entity):
    e_lower = entity.lower()
    words = set(re.findall(r'\b\w+\b', e_lower))
    scores = {}
    for category, keywords in KNOWLEDGE_BASE.items():
        score = len(words & keywords)
        if score > 0:
            scores[category] = score
    if not scores:
        return "unknown", 0.0
    best = max(scores, key=scores.get)
    total = sum(scores.values())
    confidence = round(scores[best] / total, 4)
    return best, confidence


def handler(event):
    if not isinstance(event, dict):
        return {"ok": False, "error": "event must be an object"}
    entities = event.get("entities")
    if not entities or not isinstance(entities, list):
        return {"ok": False, "error": "entities (array of strings) is required"}
    try:
        linked = []
        for entity in entities:
            if not isinstance(entity, str):
                continue
            category, confidence = _classify_entity(entity)
            linked.append({
                "entity": entity,
                "category": category,
                "confidence": confidence,
                "uri": f"kb://{category}/{entity.lower().replace(' ', '_')}"
            })
        return {
            "ok": True,
            "result": linked,
            "linked": linked,
            "count": len(linked)
        }
    except Exception as e:
        return {"ok": False, "error": str(e)}
